#include <cstdio>
#include <vector>
using namespace std;

using ll = long long;
using i128 = __int128_t;

int main() {
    ll n, mod;
    scanf("%lld%lld", &n, &mod);

    vector<ll> fact(n + 1, 1 % mod);
    for (ll i = 1; i <= n; ++i)
        fact[i] = (i128)fact[i - 1] * i % mod;

    ll res = 0;
    for (ll i = 1; i <= n; ++i) {
        ll k = n - i + 1;
        ll tmp = (i128)fact[i] * fact[k] % mod;
        tmp = (i128)tmp * k % mod;
        res = (res + tmp) % mod;
    }

    printf("%lld\n", res);
    return 0;
}

